using System.Numerics;
namespace Shape;

public interface ISource {
    int ByteLength { get; }
    void Rewind();
    bool TryGetNext(out ReadOnlySpan<byte> bytes);
}

public static class Kernel {
    public static uint Tiny<TSource>(TSource source, uint fence)
        where TSource : struct, ISource, allows ref struct {
        if (source.ByteLength < 0 || source.ByteLength > 252 || (source.ByteLength & 3) != 0) throw new ArgumentException();
        var scan = new Scan(fence);
        source.Rewind();
        while (source.TryGetNext(out ReadOnlySpan<byte> bytes)) scan.Append(bytes);
        if (scan.Bytes != source.ByteLength || scan.Pending != 0) throw new ArgumentException();
        return scan.Key;
    }

    public static uint Tiny(ReadOnlySpan<byte> first, ReadOnlySpan<byte> second, ReadOnlySpan<byte> third, uint fence) {
        var scan = new Scan(fence);
        scan.Append(first); scan.Append(second); scan.Append(third);
        if (scan.Bytes > 252 || scan.Pending != 0) throw new ArgumentException();
        return scan.Key;
    }

    private struct Scan(uint fence) {
        private readonly uint _fence = fence;
        private ulong _bits = fence < 64 ? 1UL << (int)fence : 0;
        private uint _word;
        public int Pending, Bytes;
        public uint Key => (uint)BitOperations.TrailingZeroCount(~_bits);
        public void Append(ReadOnlySpan<byte> bytes) {
            Bytes += bytes.Length;
            foreach (byte b in bytes) {
                _word |= (uint)b << (Pending++ * 8);
                if (Pending != 4) continue;
                uint candidate = _word ^ _fence;
                if (candidate < 64) _bits |= 1UL << (int)candidate;
                _word = 0; Pending = 0;
            }
        }
    }
}

using System.Buffers.Binary;
using System.Text.Json;
using Shape;

Span<byte> body = stackalloc byte[252];
uint[] fences = [0u, 1u, 63u, 64u, 0x32464252u];
int cases = 0;
foreach (uint fence in fences) {
    int n = 0;
    for (uint key = 0; key < 64 && n < 63; key++) {
        if (key == fence) continue;
        BinaryPrimitives.WriteUInt32LittleEndian(body[(n++ * 4)..], key ^ fence);
    }
    var source = new ThreeSpans(body[..1], body[1..128], body[128..]);
    uint keyGeneric = Kernel.Tiny(source, fence);
    uint keyDirect = Kernel.Tiny(body[..1], body[1..128], body[128..], fence);
    if (keyGeneric != keyDirect || keyGeneric == fence) throw new Exception("Shape mismatch");
    for (int offset = 0; offset < body.Length; offset += 4)
        if ((BinaryPrimitives.ReadUInt32LittleEndian(body[offset..]) ^ keyGeneric) == fence) throw new Exception("Forbidden key");
    if (fence < 64 && keyGeneric != 64) throw new Exception("Expected implicit Key64");
    cases++;
}
var borrowed = new ThreeSpans(body[..1], body[1..128], body[128..]);
for (int i = 0; i < 100; i++) _ = Kernel.Tiny(borrowed, 0x32464252u);
long before = GC.GetAllocatedBytesForCurrentThread();
uint sink = 0;
for (int i = 0; i < 100000; i++) sink ^= Kernel.Tiny(borrowed, 0x32464252u);
long allocated = GC.GetAllocatedBytesForCurrentThread() - before;
if (allocated != 0) throw new Exception("Unexpected boxing/allocation");
Console.WriteLine(JsonSerializer.Serialize(new { Cases = cases, AllocationBytes = allocated, Iterations = 100000, Checksum = sink,
    Scope = "Cross-assembly ref-struct source syntax and zero managed allocation; scalar shape probe, not production performance or full strategy qualification" }));

ref struct ThreeSpans(ReadOnlySpan<byte> a, ReadOnlySpan<byte> b, ReadOnlySpan<byte> c) : ISource {
    private readonly ReadOnlySpan<byte> _a = a, _b = b, _c = c;
    private int _index;
    public readonly int ByteLength => _a.Length + _b.Length + _c.Length;
    public void Rewind() => _index = 0;
    public bool TryGetNext(out ReadOnlySpan<byte> bytes) {
        switch (_index++) { case 0: bytes = _a; return true; case 1: bytes = _b; return true; case 2: bytes = _c; return true; default: bytes = default; return false; }
    }
}
